import base64,hashlib,json,os,signal,subprocess,time,shutil
from pathlib import Path
root=Path('/home/cat/projects/RK3576/rk3576_multimodal_stage5_review')
assert root.is_dir() and not root.is_symlink()
report=root/'reports/stage5_01_board'/('signal_fix_'+time.strftime('%Y%m%dT%H%M%SZ',time.gmtime()))
report.mkdir()
rows=[{'file': 'include/audio/vad_audio_worker.h', 'before_sha256': '1b6003c01667064faa99252bd47c6cf4082f04e9aa755a031fcc49202df3aa45', 'after_sha256': '897344fd93d5c9b0552c009b627c68826a14cc1722066df21d1363064ff1b517', 'data': ''}, {'file': 'src/audio/vad_audio_worker.cpp', 'before_sha256': 'ec23237150f6fa32e4781bfe8a413e1b38f67b980ec5313ebbcac3ade60d871e', 'after_sha256': '4252accf02fcce9af5fc2822c640628c63331cd59b15399ad953ed498055c91b', 'data': ''}, {'file': 'src/audio/asr_llm_tts_smoke.cpp', 'before_sha256': '3dcfe3dd1e19871fdab835b76b4410a8036a9b384f0da1e6d0aedccf950bc9a5', 'after_sha256': '28d84bce32042ce8136b27dd1c845b86f85d1168488cd51f25df0e77fa7a85e7', 'data': ''}]
patch='--- a/include/audio/vad_audio_worker.h\n+++ b/include/audio/vad_audio_worker.h\n@@ -27,6 +27,8 @@\n     void start();\n     void requestStop() noexcept;\n     void join();\n+    // Completion publication lets the owner observe stop signals without blocking in join.\n+    bool isFinished() const noexcept { return finished_.load(std::memory_order_acquire); }\n \n     // 仅在 join() 之后读取以下状态。\n     bool ok() const { return ok_; }\n@@ -48,6 +50,7 @@\n     std::size_t record_seconds_;\n \n     std::atomic<bool> stop_requested_{false};\n+    std::atomic<bool> finished_{false};\n     std::thread thread_;\n     bool started_ = false; // Lifecycle operations belong to one owner thread.\n \n--- a/src/audio/vad_audio_worker.cpp\n+++ b/src/audio/vad_audio_worker.cpp\n@@ -77,6 +77,7 @@\n         error_ = "VadAudioWorker: unknown exception";\n         queue_.close();\n     }\n+    finished_.store(true, std::memory_order_release);\n }\n \n void VadAudioWorker::runImpl()\n@@ -89,6 +90,12 @@\n             queue.close();\n         }\n     } closer{queue_};\n+\n+    if (stop_requested_.load())\n+    {\n+        ok_ = true;\n+        return;\n+    }\n \n     // ==================================================\n     // 1. 初始化 Silero VAD\n@@ -499,5 +506,6 @@\n     if (!drain_segments())\n         return;\n \n-    ok_ = !stop_requested_.load();\n-}\n+    // A requested stop is successful if capture/VAD cleanup and final flush succeeded.\n+    ok_ = true;\n+}\n--- a/src/audio/asr_llm_tts_smoke.cpp\n+++ b/src/audio/asr_llm_tts_smoke.cpp\n@@ -14,6 +14,8 @@\n #include "video/latest_frame_buffer.h"\n \n #include <chrono>\n+#include <atomic>\n+#include <cerrno>\n #include <condition_variable>\n #include <cstddef>\n #include <cstdint>\n@@ -24,8 +26,70 @@\n #include <stdexcept>\n #include <string>\n #include <utility>\n+#include <thread>\n+\n+#include <pthread.h>\n+#include <signal.h>\n \n #include <unistd.h>\n+\n+namespace {\n+// Construct before SDKs/workers: all descendant threads inherit the blocked set.\n+// sigtimedwait runs in an ordinary thread; there is no asynchronous signal handler.\n+class StopSignals {\n+public:\n+    StopSignals()\n+    {\n+        sigemptyset(&signals_);\n+        sigaddset(&signals_, SIGINT);\n+        sigaddset(&signals_, SIGTERM);\n+        if (pthread_sigmask(SIG_BLOCK, &signals_, &previous_) != 0)\n+            throw std::runtime_error("Cannot block stop signals");\n+        try\n+        {\n+            thread_ = std::thread([this] {\n+                const timespec interval{0, 100000000};\n+                while (!finished_.load())\n+                {\n+                    const int received = sigtimedwait(&signals_, nullptr, &interval);\n+                    if (received == SIGINT || received == SIGTERM)\n+                    {\n+                        int empty = 0;\n+                        signal_.compare_exchange_strong(empty, received);\n+                    }\n+                    else if (received < 0 && errno != EAGAIN && errno != EINTR)\n+                    {\n+                        wait_failed_.store(true);\n+                        break;\n+                    }\n+                }\n+            });\n+        }\n+        catch (...)\n+        {\n+            pthread_sigmask(SIG_SETMASK, &previous_, nullptr);\n+            throw;\n+        }\n+    }\n+    ~StopSignals()\n+    {\n+        finished_.store(true);\n+        if (thread_.joinable()) thread_.join();\n+        pthread_sigmask(SIG_SETMASK, &previous_, nullptr);\n+    }\n+    StopSignals(const StopSignals&) = delete;\n+    StopSignals& operator=(const StopSignals&) = delete;\n+    int received() const noexcept { return signal_.load(); }\n+    bool failed() const noexcept { return wait_failed_.load(); }\n+private:\n+    sigset_t signals_{};\n+    sigset_t previous_{};\n+    std::atomic<int> signal_{0};\n+    std::atomic<bool> finished_{false};\n+    std::atomic<bool> wait_failed_{false};\n+    std::thread thread_;\n+};\n+} // namespace\n \n // ==========================================================\n // Stage 3.5\n@@ -189,6 +253,8 @@\n     }\n \n     std::string error;\n+\n+    StopSignals stop_signals;\n \n     // ------------------------------------------------------\n     // 4. 初始化 RKLLM\n@@ -988,9 +1054,27 @@\n     // 15. 等待录音/VAD 和 ASR 完成\n     // ------------------------------------------------------\n \n+    bool stop_reported = false;\n+    while (!producer.isFinished())\n+    {\n+        if (stop_signals.received() != 0 || stop_signals.failed())\n+        {\n+            producer.requestStop();\n+            if (!stop_reported)\n+            {\n+                std::lock_guard<std::mutex> out(print_mutex);\n+                std::cout << "[Shutdown] signal=" << stop_signals.received()\n+                          << " stopping capture; draining accepted work\\n" << std::flush;\n+                stop_reported = true;\n+            }\n+        }\n+        std::this_thread::sleep_for(std::chrono::milliseconds(20));\n+    }\n     producer.join();\n \n     consumer.join();\n+    asr.shutdown();\n+    std::cout << "[Shutdown] capture/VAD and ASR joined; recognizer destroyed\\n" << std::flush;\n \n     // 此时 ASRWorker 已经退出，\n     // 不会继续向 LLMWorker 提交新请求。\n@@ -1099,6 +1183,8 @@\n     // 才允许释放 RKLLM Runtime。\n     llm.shutdown();\n \n+    std::cout << "[Shutdown] LLM joined; Qwen runtime destroyed\\n" << std::flush;\n+\n     // ------------------------------------------------------\n     // 19. 等待全部 TTS 任务完成\n     // ------------------------------------------------------\n@@ -1131,12 +1217,18 @@\n     tts_worker.requestStop();\n     tts_worker.join();\n \n+    std::cout << "[Shutdown] TTS joined; playback_xruns=" << playback.xrunCount()\n+              << \'\\n\' << std::flush;\n+\n     // 只有 Worker 退出以后，\n     // 才能安全关闭 ALSA 和 TTSService。\n     playback.close();\n     tts.shutdown();\n     if (camera) camera->stop();\n     if (vlm) vlm->shutdown();\n+    std::cout << "[Shutdown] playback/TTS closed; Camera stopped; VLM destroyed\\n"\n+              << "[Shutdown] complete signal=" << stop_signals.received() << \'\\n\'\n+              << std::flush;\n \n     // ------------------------------------------------------\n     // 21. 输出整个语音交互链路的统计\n@@ -1227,7 +1319,9 @@\n         llm_drained &&\n         tts_drained &&\n \n-        (llm_accepted > 0 || (enable_vision && vision_successful > 0)) &&\n+        !stop_signals.failed() &&\n+        (stop_signals.received() != 0 || llm_accepted > 0 ||\n+         (enable_vision && vision_successful > 0)) &&\n         llm_accepted == llm_completed &&\n         llm_successful == llm_accepted &&\n         llm_failed == 0 &&\n@@ -1242,7 +1336,7 @@\n         tts_empty == 0;\n \n     std::cout\n-        << (passed ? "PASS\\n" : "FAIL\\n");\n+        << (passed ? (stop_signals.received() != 0 ? "STOPPED\\n" : "PASS\\n") : "FAIL\\n");\n \n     return passed ? 0 : 1;\n }\n'

for row in rows:
    p=root/row['file'];assert p.is_file() and not p.is_symlink()
    assert hashlib.sha256(p.read_bytes()).hexdigest()==row['before_sha256'],'unexpected isolated source version'
for row in rows:
    p=root/row['file']; old=report/'original'/row['file'];old.parent.mkdir(parents=True,exist_ok=True);old.write_bytes(p.read_bytes())
    data=base64.b64decode(row['data']);assert hashlib.sha256(data).hexdigest()==row['after_sha256']
    tmp=p.with_name(p.name+'.stage5_signal_fix_tmp')
    with tmp.open('xb') as f:f.write(data)
    os.replace(tmp,p)
(report/'signal_fix.patch').write_text(patch)
(report/'manifest.json').write_text(json.dumps([{k:v for k,v in row.items() if k!='data'} for row in rows],indent=2)+'\n')
cmd=['bash','-c','source "$1/tools/stage5_board_paths.sh"; exec timeout --signal=TERM --kill-after=15s 600s cmake --build "$1/build/stage5_01_board" --parallel 3','signalfix',str(root)]
(report/'build.command.json').write_text(json.dumps(cmd,indent=2)+'\n')
with (report/'build.stdout.log').open('wb') as out,(report/'build.stderr.log').open('wb') as err,(report/'disk_samples.jsonl').open('w') as samples:
    process=subprocess.Popen(cmd,stdout=out,stderr=err,start_new_session=True)
    started=time.monotonic();reason=None
    while process.poll() is None:
        free=shutil.disk_usage(root).free;samples.write(json.dumps({'time':time.time(),'free_bytes':free})+'\n');samples.flush()
        if free<500*1024**2 or time.monotonic()-started>620:
            reason='disk_below_500_MiB' if free<500*1024**2 else 'build_timeout'
            os.killpg(process.pid,signal.SIGTERM)
            try:process.wait(timeout=15)
            except subprocess.TimeoutExpired:os.killpg(process.pid,signal.SIGKILL);process.wait(timeout=10)
            break
        time.sleep(1)
    code=process.wait()
(report/'build.result.json').write_text(json.dumps({'returncode':code,'stop_reason':reason},indent=2)+'\n')
print((report/'build.stdout.log').read_text(),flush=True);print((report/'build.stderr.log').read_text(),flush=True)
assert code==0 and reason is None,'build failed; original diagnostics retained'
cmd=['bash','-c','source "$1/tools/stage5_board_paths.sh"; exec timeout --signal=TERM --kill-after=10s 120s ctest --test-dir "$1/build/stage5_01_board" --output-on-failure --timeout 30 --output-junit "$2/ctest.xml"','phase3',str(root),str(report)]
with (report/'ctest.stdout.log').open('wb') as out,(report/'ctest.stderr.log').open('wb') as err:
    r=subprocess.run(cmd,stdout=out,stderr=err,timeout=140)
(report/'ctest.exit_code.txt').write_text(str(r.returncode)+'\n')
print((report/'ctest.stdout.log').read_text(),flush=True)
assert r.returncode==0,'CTest failed'
for sig in ('SIGINT','SIGTERM'):
    cmd=['python3','-I',str(root/'tools/stage5_board_phase3_run.py'),'--name','fixed_idle_'+sig.lower(),'--signal',sig,'--trigger','ready','--delay','2','--seconds','120','--timeout','180','--grace','40']
    r=subprocess.run(cmd,timeout=240)
    assert r.returncode==0
    outcome=json.loads((root/'reports/stage5_01_board'/('fixed_idle_'+sig.lower())/'result.json').read_text())
    assert outcome['returncode']==0 and outcome['shutdown_complete_marker'] and not outcome['forced_kill'] and not outcome['timeout'],'signal regression failed'
print('FIX_BUILD_CTEST_IDLE_SIGNALS_COMPLETE',report,flush=True)
